using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using DuckGame.Maps.V08;
namespace DuckGame.Maps.V10 {
[InitializeOnLoad]public static class EnemyGroveBuilder {
 const string R="Assets/DuckGame/Maps/V10/Generated/",D="docs/verification/v10/";static int meshId;static Material bark,moss,cap,cream,ink,amber;static Transform body;
 static EnemyGroveBuilder(){EditorApplication.update+=Tick;}
 static void Tick(){string q=D+"build-request.txt";if(EditorApplication.isCompiling||!File.Exists(q))return;var cmd=File.ReadAllText(q).Trim();if(cmd.Length==0)return;if(cmd=="stop"&&EditorApplication.isPlaying){EditorApplication.isPlaying=false;return;}if(EditorApplication.isPlaying)return;File.WriteAllText(q,"");try{if(cmd=="build")Build();else if(cmd=="visibility"){ApplyVisibility(UnityEngine.Object.FindObjectOfType<MerchantTrade>());AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());}else if(cmd=="places"){var enemies=UnityEngine.Object.FindObjectsOfType<ForestEnemy>().Where(e=>e.kind=="Mosswood").OrderBy(e=>e.transform.position.z).ToArray();enemies[0].transform.position=new Vector3(3,.02f,2);enemies[1].transform.position=new Vector3(-3,.02f,10);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());}else if(cmd=="limbs"){foreach(var n in new[]{"Capling","Mosswood"}){var path=R+n+".prefab";var root=PrefabUtility.LoadPrefabContents(path);try{foreach(var f in root.GetComponentsInChildren<MeshFilter>())if((f.name.Contains("foot")||f.name.Contains("mitten")||f.name.Contains("arm"))&&f.GetComponent<BoxCollider>()==null)f.gameObject.AddComponent<BoxCollider>().size=Vector3.one*2;PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());}else if(cmd=="play")EditorApplication.isPlaying=true;}catch(Exception ex){File.WriteAllText(D+"build-error.txt",ex.ToString());Debug.LogException(ex);}}
 static Material Mat(string name,Color color){var m=new Material(Shader.Find("Duck Game/V09/Tailored Toon"));m.name=name;m.SetVector("_Tint",color);m.SetFloat("_Sheen",.008f);AssetDatabase.CreateAsset(m,R+name+".mat");return m;}
 static void Build(){string path=R+"EnemyGrove.unity";if(File.Exists(path))throw new Exception("V10 exists; refusing overwrite");var active=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(active.isDirty&&!EditorSceneManager.SaveScene(active,D+"baseline/Unsaved.unity",true))throw new Exception("Safety save failed");if(!AssetDatabase.CopyAsset("Assets/DuckGame/Maps/V09/Generated/PolishedGrove.unity",path))throw new Exception("Scene copy failed");var scene=EditorSceneManager.OpenScene(path);var trade=UnityEngine.Object.FindObjectOfType<MerchantTrade>();trade.shooter.GetComponent<CombatFeedback>().externalMarker=true;trade.shooter.gameObject.AddComponent<EnemyHitFeedback>();
 bark=Mat("Warm carved wood",new Color(.42f,.30f,.20f));moss=Mat("Quiet moss",new Color(.41f,.49f,.32f));cap=Mat("Muted terracotta cap",new Color(.67f,.38f,.27f));cream=Mat("Mushroom cream",new Color(.79f,.75f,.58f));ink=Mat("Soft charcoal eyes",new Color(.065f,.075f,.068f));amber=Mat("Amber eye glint",new Color(.93f,.74f,.34f));
 var mushroom=MakeEnemy(false);var tree=MakeEnemy(true);var prefabs=new[]{mushroom,tree,mushroom,tree};var positions=new[]{new Vector3(-4,.02f,3),new Vector3(3,.02f,2),new Vector3(5,.02f,10),new Vector3(-3,.02f,10)};for(int i=0;i<4;i++){var e=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[i]);e.name=(i%2==0?"Capling":"Mosswood")+" practice "+(i+1);e.transform.SetPositionAndRotation(positions[i],Quaternion.Euler(0,180+i*7,0));}
 var ring=new Material(Shader.Find("Duck Game/V10/Short Impact"));ring.name="Short contact ring";ring.SetFloat("_Ring",1);AssetDatabase.CreateAsset(ring,R+"Short contact ring.mat");var streak=new Material(ring);streak.name="Short sparks";streak.SetFloat("_Ring",0);AssetDatabase.CreateAsset(streak,R+"Short sparks.mat");var effect=ScriptableObject.CreateInstance<ForestImpact>();effect.ring=ring;effect.streak=streak;AssetDatabase.CreateAsset(effect,R+"ForestImpact.asset");new GameObject("V10 prewarmed effects").AddComponent<ForestImpactStartup>().effect=effect;var config=UnityEngine.Object.Instantiate(trade.shooter.config);config.name="V10 orb configuration";config.replaceDefaultImpact=true;config.impactEffect=effect;AssetDatabase.CreateAsset(config,R+"OrbConfigV10.asset");trade.shooter.config=config;
 ApplyVisibility(trade);if(!EditorSceneManager.SaveScene(scene,path))throw new Exception("Save failed");AssetDatabase.SaveAssets();File.WriteAllText(D+"build.txt","V10 saved:4 original enemy samples,2 kinds; meshes="+meshId);Debug.Log("V10_BUILD_OK");}
 static void ApplyVisibility(MerchantTrade trade){trade.view.minPitch=-90;var cache=new Dictionary<Material,Material>();foreach(var r in trade.motor.GetComponentsInChildren<SkinnedMeshRenderer>()){var ms=r.sharedMaterials;for(int i=0;i<ms.Length;i++){var src=ms[i];if(src.shader.name.Contains("Omit Band")||src.shader.name.StartsWith("Duck Game/V10/Fade"))continue;if(cache.TryGetValue(src,out var saved)){ms[i]=saved;continue;}string name="Player_"+Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(src));var m=new Material(src);m.name=name;m.shader=Shader.Find(r.name.EndsWith("_Outline")?"Duck Game/V10/Fade Pixel Outline":"Duck Game/V10/Fade Toon");m.SetFloat("_V10Visibility",1);string path=R+name+".mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing==null){AssetDatabase.CreateAsset(m,path);saved=m;}else{EditorUtility.CopySerialized(m,existing);UnityEngine.Object.DestroyImmediate(m);saved=existing;EditorUtility.SetDirty(saved);}cache[src]=saved;ms[i]=saved;}r.sharedMaterials=ms;}var visibility=trade.motor.GetComponent<UpwardPlayerVisibility>();if(visibility==null)visibility=trade.motor.gameObject.AddComponent<UpwardPlayerVisibility>();var readyPath=R+"Ready orb fade.mat";var ready=AssetDatabase.LoadAssetAtPath<Material>(readyPath);if(ready==null){ready=new Material(trade.shooter.orbMaterial);ready.name="Ready orb fade";ready.shader=Shader.Find("Duck Game/V10/Ready Pearl");AssetDatabase.CreateAsset(ready,readyPath);}visibility.shooter=trade.shooter;visibility.readyMaterial=ready;visibility.view=trade.view;visibility.player=trade.motor.transform;}
 static GameObject MakeEnemy(bool tree){var root=new GameObject(tree?"Mosswood":"Capling");body=new GameObject("Responsive body").transform;body.SetParent(root.transform,false);var receiver=root.AddComponent<ForestEnemy>();receiver.body=body;receiver.kind=tree?"Mosswood":"Capling";var col=root.AddComponent<CapsuleCollider>();col.center=new Vector3(0,1.05f,0);col.height=2.1f;col.radius=tree?.61f:.53f;
 if(tree){Ell("Rounded wood trunk",new Vector3(0,1.02f,0),new Vector3(.57f,.90f,.42f),bark);Ell("Moss shoulder crown",new Vector3(0,1.78f,0),new Vector3(.65f,.25f,.47f),moss);for(int side=-1;side<=1;side+=2){Ell("Broad rooted foot",new Vector3(side*.35f,.18f,.12f),new Vector3(.37f,.18f,.48f),bark);var arm=Ell("Stubby branch arm",new Vector3(side*.78f,1.05f,0),new Vector3(.25f,.48f,.26f),bark);arm.transform.localRotation=Quaternion.Euler(0,0,side*25);Ell("Leaf ear",new Vector3(side*.63f,1.9f,0),new Vector3(.27f,.11f,.16f),moss).transform.localRotation=Quaternion.Euler(0,0,side*35);}}
 else{Ell("Pear mushroom body",new Vector3(0,.82f,0),new Vector3(.48f,.66f,.38f),cream);for(int side=-1;side<=1;side+=2){Ell("Round small foot",new Vector3(side*.30f,.15f,.12f),new Vector3(.25f,.15f,.32f),bark);Ell("Small mitten",new Vector3(side*.53f,.79f,.02f),new Vector3(.16f,.30f,.18f),cream);}Cap();Ell("Soft undercap lip",new Vector3(0,1.48f,0),new Vector3(.85f,.10f,.67f),cream);}
 float y=tree?1.23f:1.03f,z=tree?.405f:.355f;for(int side=-1;side<=1;side+=2){Ell("Inset dark eye",new Vector3(side*.205f,y,z),new Vector3(.105f,.155f,.045f),ink);Ell("Amber iris",new Vector3(side*.205f,y+.012f,z+.039f),new Vector3(.045f,.079f,.016f),amber);Ell("Tiny eye light",new Vector3(side*.205f-.014f,y+.055f,z+.057f),new Vector3(.014f,.021f,.007f),cream);}
 Ell("Small neutral mouth",new Vector3(0,y-.22f,z+.015f),new Vector3(.10f,.025f,.018f),ink);var prefab=PrefabUtility.SaveAsPrefabAsset(root,R+(tree?"Mosswood":"Capling")+".prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static GameObject Ell(string name,Vector3 position,Vector3 scale,Material mat){var vs=new List<Vector3>();var ts=new List<int>();int lat=14,lon=28;for(int j=0;j<=lat;j++)for(int i=0;i<=lon;i++){float a=j*Mathf.PI/lat,b=i*Mathf.PI*2/lon;vs.Add(new Vector3(Mathf.Sin(a)*Mathf.Cos(b),Mathf.Cos(a),Mathf.Sin(a)*Mathf.Sin(b)));}for(int j=0;j<lat;j++)for(int i=0;i<lon;i++){int a=j*(lon+1)+i;ts.AddRange(new[]{a,a+1,a+lon+1,a+1,a+lon+2,a+lon+1});}var g=MeshPart(name,vs.ToArray(),ts.ToArray(),mat);g.transform.localPosition=position;g.transform.localScale=scale;if(name.Contains("foot")||name.Contains("mitten")||name.Contains("arm"))g.AddComponent<BoxCollider>().size=Vector3.one*2;return g;}
 static void Cap(){var vs=new List<Vector3>();var ts=new List<int>();int n=48;var rings=new[]{new Vector2(.02f,1.98f),new Vector2(.34f,1.94f),new Vector2(.68f,1.76f),new Vector2(.93f,1.55f),new Vector2(.91f,1.49f),new Vector2(.02f,1.48f)};for(int j=0;j<rings.Length;j++)for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;vs.Add(new Vector3(Mathf.Cos(a)*rings[j].x,rings[j].y,Mathf.Sin(a)*rings[j].x*.76f));}for(int j=0;j<rings.Length-1;j++)for(int i=0;i<n;i++){int a=j*(n+1)+i;ts.AddRange(new[]{a,a+1,a+n+1,a+1,a+n+2,a+n+1});}var g=MeshPart("Soft broad mushroom cap",vs.ToArray(),ts.ToArray(),cap);g.AddComponent<MeshCollider>().sharedMesh=g.GetComponent<MeshFilter>().sharedMesh;}
 static GameObject MeshPart(string name,Vector3[] vs,int[] triangles,Material mat){var mesh=new Mesh{name=name};mesh.vertices=vs;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,R+"EnemyMesh_"+(meshId++)+".asset");var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(body,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=mat;return go;}
}
}
